#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# The report relay on Cloudflare (docs/relay.md): what only the maintainer can do.
# Run it from anywhere in the repository: bash scripts/setup-relay.sh
# The relay's address and your maintainer's token are remembered in .scratch/relay.env (git-ignored)
# for a re-run and for reading reports by hand; the GitHub token goes only to Cloudflare, never to a file.
cd "$(dirname "$0")/.."
# Not .env (the library's default): .scratch/ is where the project keeps what's private.
ENV_FILE=.scratch/relay.env
mkdir -p "$(dirname "$ENV_FILE")"
REPO="pablonification/edunex-plus"

TOTAL_STAGES=8

banner "The report relay (Cloudflare)"

stage "A Cloudflare account"
say "The relay runs on Cloudflare's free plan. It needs no card."
open_url "https://dash.cloudflare.com/sign-up"
step "Sign up, or sign in if you have an account already."
pause "Press Enter once you're signed in to Cloudflare"

stage "wrangler, Cloudflare's tool, signed in"
say "This installs the relay's packages, then signs wrangler in to your Cloudflare account."
step "A browser window asks you to allow wrangler: allow it, then come back here."
(cd relay && npm ci --no-audit --no-fund)
(cd relay && npx wrangler login)

stage "Put the relay online"
say "This uploads the relay to your account, with its storage and its cron trigger."
say "The first time, wrangler asks you to pick a workers.dev subdomain: any short name works,"
say "it becomes part of the relay's address."
if confirm "Put the relay online now?"; then (cd relay && npx wrangler deploy); fi
step "At the end, wrangler printed the address: https://edunex-plus-relay.<subdomain>.workers.dev"
ask RELAY_URL "Paste the relay's address:"
RELAY_URL="${RELAY_URL%/}"
write_env RELAY_URL "$RELAY_URL"
set_var RELAY_URL "$RELAY_URL"

stage "The token the relay files issues with"
say "A fine-grained GitHub token that can read and write this repository's issues, and nothing else."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: edunex-plus-relay. Resource owner: pablonification."
step "Expiration: the longest offered. Put a reminder in your calendar a week before it ends."
step "Repository access: Only select repositories, then pablonification/edunex-plus."
step "Permissions, under Repository: Issues, Read and write. Nothing else."
step "Generate token, then copy it: GitHub shows it once."
ask_secret GITHUB_TOKEN "Paste the token (hidden), or press Enter to keep the one already set:"
if [[ -n "$GITHUB_TOKEN" ]]; then
  printf '%s' "$GITHUB_TOKEN" | (cd relay && npx wrangler secret put GITHUB_TOKEN)
else
  note "Kept the token the relay already has."
fi
unset GITHUB_TOKEN

stage "Your token, to read reports"
say "The maintainer's token reads any report the relay keeps: you, by hand, and the fix bot."
MAINTAINER_TOKEN=$(_existing MAINTAINER_TOKEN || true)
if [[ -z "$MAINTAINER_TOKEN" ]]; then MAINTAINER_TOKEN=$(node -e 'console.log(require("node:crypto").randomBytes(32).toString("hex"))'); fi
write_env MAINTAINER_TOKEN "$MAINTAINER_TOKEN"
printf '%s' "$MAINTAINER_TOKEN" | (cd relay && npx wrangler secret put MAINTAINER_TOKEN)
set_secret RELAY_MAINTAINER_TOKEN "$MAINTAINER_TOKEN"
note "It's in $ENV_FILE. Keep a copy in your password manager too."
unset MAINTAINER_TOKEN
pause

stage "Check it answers"
if curl -fsS "$RELAY_URL/v1/health"; then
  printf '\n'
  say "It answers."
else
  warn "It didn't answer. Check the address, then: cd relay && npm run logs"
  SKIPPED+=("the relay answering at $RELAY_URL/v1/health")
fi
pause

stage "The from-relay label"
say "The relay marks its issues with it. No issue form can, so it says an issue really came from the relay."
if gh label create from-relay --repo "$REPO" --color 5319e7 --description "Filed by the report relay from a Student's report" --force >/dev/null 2>&1; then
  printf '  %s✓ made%s the label from-relay\n' "$GREEN" "$RESET"
else
  SKIPPED+=("the from-relay label (docs/relay.md, step 7)")
  warn "couldn't make the label: gh isn't signed in. docs/relay.md, step 7, has the command."
fi
pause

stage "Turn it on in the app"
say "The app offers only LINE and GitHub until it knows the relay's address."
step "The app's side of the relay comes in its own pull request, with REPORT_RELAY_URL empty."
step "Once it's merged, set REPORT_RELAY_URL to: $RELAY_URL"
step "Open a pull request with that line, merge it, and release (CONTRIBUTING.md, Releases)."
pause "Press Enter to finish"

finish
